"""Build timeline.js (beat times + caption phrases) from audio/words.json. VO = narration offset in the film."""
import json
VO = 0.30; TAIL = 1.40
d = json.load(open('audio/words.json')); w = d['words']
B = dict(french=4, uranium1=7, gabon=12, missing=16, natural=19, everywhere=22, share=27, zero=33, this_ore=38, less=41, like=42, reactor1=51,
         but_rock=52, rock=56, nobody=57, about2b=62, ago=65, richer=68, three=70, close=76, groundwater=83, ore_soak=86, water_slows=87,
         neutrons=89, split=93, easily=96, chain=98, own=103, heat=106, boiled=107, away=110, without=111, stopped=115, cooled=118,
         seeped=120, switched=125, again=127, half=129, off=136, hundred=140, years1=142, cant=144, today=146, decays=151, rest=155,
         natural2=157, enough=162, receipts=168, leftovers=170, fundamental=176, constants=177, changed=181, less2=183, million=189,
         twob=191, nuclear=195, nobody2=197, built=198, still=201, teaching=202, us=203)
beats = {k: round(w[i]['start'] + VO, 3) for k, i in B.items()}
C = [(0,2,'In 1972,'),(3,12,'a French lab tested uranium from a mine in Gabon.'),(13,18,'Some of its fuel was missing.'),
     (19,23,'Natural uranium almost everywhere holds'),(24,32,'the same tiny share of uranium-235:'),(33,37,'0.72%.'),(38,41,'This ore had less.'),
     (42,51,'Like fuel that had already been burned in a reactor.'),(52,56,'But this was a rock.'),(57,60,'Nobody had built anything.'),
     (61,65,'About two billion years ago,'),(66,68,'uranium was richer:'),(69,75,'roughly 3% uranium-235,'),(76,82,'close to what our power reactors use.'),
     (83,86,'Groundwater soaked the ore.'),(87,90,'Water slows neutrons down,'),(91,96,'so they split uranium more easily.'),(97,103,'A chain reaction started on its own.'),
     (104,110,'Then its heat boiled the water away.'),(111,115,'Without it, the reaction stopped.'),(116,118,'The rock cooled,'),(119,122,'water seeped back in...'),
     (123,127,'and it switched on again.'),(128,132,'About half an hour on,'),(133,136,'a few hours off,'),(137,142,'for over a hundred thousand years.'),
     (143,146,"It can't happen today."),(147,155,'Uranium-235 decays faster than the rest,'),(156,162,'and natural ore no longer has enough.'),
     (163,168,'But the rock kept the receipts.'),(169,172,'Its leftovers show that'),(173,179,'one of the fundamental constants of physics'),
     (180,189,'has changed by less than one part in ten million,'),(190,193,'in two billion years.'),(194,198,'A nuclear reactor nobody built...'),(199,203,"and it's still teaching us.")]
caps = []
for k, (a, b, s) in enumerate(C):
    t0 = w[a]['start'] + VO
    t1 = (C[k + 1] and w[C[k + 1][0]]['start'] + VO - .05) if k + 1 < len(C) else w[b]['end'] + VO + .9
    t1 = min(t1, w[b]['end'] + VO + .8)
    caps.append({'s': s, 't0': round(t0, 3), 't1': round(t1, 3)})
duration = round(VO + d['duration_s'] + TAIL, 3)
open('timeline.js', 'w').write('// generated by make_timeline.py from audio/words.json; caption timing ESTIMATED (machine alignment)\n'
    f'export const VO = {VO}, DURATION = {duration};\nexport const B = {json.dumps(beats)};\nexport const CAPTIONS = {json.dumps(caps)};\n')
print('duration', duration, 'frames', round(duration * 30), 'captions', len(caps))
